#include <iostream>
#include <algorithm>

using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long n, a, b, c;
    cin >> n >> a >> b >> c;

    if (n < b || a <= b - c) {
        cout << n / a;
    } else {
        long long count = (n - b) / (b - c) + 1;
        n -= count * (b - c);
        cout << count + n / a;
    }

    return 0;
}

